<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted} from 'vue';
import {SwitchRoot,SwitchThumb} from 'reka-ui';
import {Monitor,Bot,Layers3,ShieldCheck,ArrowUpRight,Globe2,FolderKanban} from '@lucide/vue';
import HookSetup from './HookSetup.vue';
import TrackingCleanup from './TrackingCleanup.vue';
import WebsiteRules from './WebsiteRules.vue';
import LinearConnection from './LinearConnection.vue';
import {native,openAccessibilitySettings,startupItem,type StartupItemStatus,type CaptureStatus} from './transport.ts';
import type {CaptureSettings} from '../capture/settings.ts';
const props=defineProps<{status:CaptureStatus|null;busy:boolean}>();
const emit=defineEmits<{change:[settings:Partial<CaptureSettings>];error:[message:string]}>();
const content=ref<HTMLElement|null>(null),active=ref('agents');
const agents=computed(()=>props.status?.sources.filter(source=>source.kind==='agent')||[]);
const pollers=computed(()=>props.status?.sources.filter(source=>source.kind==='poller')||[]);
const providers=computed(()=>agents.value.map(source=>source.id));
const agent=(id:string)=>agents.value.find(source=>source.id===id);
const navigation=computed(()=>[{id:'agents',title:'Agents',icon:Bot,child:false},...agents.value.map(source=>({id:source.id,title:source.name,icon:Bot,child:true})),{id:'editors',title:'ADE / IDE',icon:Layers3,child:false},...pollers.value.map(source=>({id:source.id,title:source.name,icon:Layers3,child:true})),{id:'browsers',title:'Browsers',icon:Globe2,child:false},{id:'projects',title:'Projects',icon:FolderKanban,child:false},{id:'system',title:'System',icon:Monitor,child:false}]);
const browsers=computed(()=>props.status?.sources.filter(source=>source.kind==='browser').map(source=>({key:source.setting,name:source.name,detail:source.detail||source.name,initial:source.name[0],tone:source.id}))||[]);
const hooksEnabled=computed(()=>agents.value.filter(source=>props.status?.surfaces[source.setting]).length);
const usageEnabled=(id:string)=>Boolean(props.status?.surfaces.tokenUsage&&props.status.surfaces[agent(id)?.usageSetting||'']);
const usageCount=computed(()=>providers.value.filter(usageEnabled).length);
const allHookSettings=(enabled:boolean)=>Object.fromEntries(agents.value.map(source=>[source.setting,enabled]));
const allUsageSettings=(enabled:boolean)=>({tokenUsage:enabled,...Object.fromEntries(agents.value.map(source=>[source.usageSetting,enabled]))});
const idleChoices=Array.from({length:60},(_,index)=>index+1);
const startup=ref<StartupItemStatus|null>(null),startupBusy=ref(false),startupError=ref('');
async function refreshStartup(){if(!native)return;try{startup.value=await startupItem('status');startupError.value='';}catch(error){startupError.value=String(error);}}
async function changeStartup(enabled:boolean){startupBusy.value=true;startupError.value='';try{startup.value=await startupItem(enabled?'enable':'disable');}catch(error){startupError.value=String(error);}finally{startupBusy.value=false;}}
async function openStartupSettings(){try{await startupItem('settings');}catch(error){startupError.value=String(error);}}
function scrollToSection(id:string){const root=content.value,target=root?.querySelector<HTMLElement>('#settings-'+id);if(!root||!target)return;active.value=id;root.scrollTo({top:target.offsetTop-24,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});target.focus({preventScroll:true});}
function syncNavigation(){const root=content.value;if(!root)return;const top=root.scrollTop+36;let current='agents';for(const item of navigation.value){const section=root.querySelector<HTMLElement>('#settings-'+item.id);if(section&&section.offsetTop<=top)current=item.id;}active.value=current;}
function setUsage(provider:string,enabled:boolean){emit('change',{tokenUsage:true,...Object.fromEntries(agents.value.map(source=>[source.usageSetting,usageEnabled(source.id)])),[agent(provider)?.usageSetting||'']:enabled});}
function setIdle(kind:'humanIdleMinutes'|'agentIdleMinutes',event:Event){emit('change',{[kind]:Number((event.target as HTMLSelectElement).value)});}
async function openPermission(){try{await openAccessibilitySettings();}catch(e){emit('error',String(e));}}
onMounted(()=>{syncNavigation();void refreshStartup();window.addEventListener('focus',refreshStartup);});
onUnmounted(()=>window.removeEventListener('focus',refreshStartup));
</script>
<template>
<div class="settings-layout">
 <nav class="settings-sidebar" aria-label="Settings sections"><h1>Settings</h1><a v-for="item in navigation" :key="item.id" :href="'#settings-'+item.id" :class="['settings-nav',{child:item.child,active:active===item.id,'section-start':item.id==='editors'||item.id==='browsers'}]" :aria-current="active===item.id?'location':undefined" @click.prevent="scrollToSection(item.id)"><component :is="item.icon" v-if="!item.child" :size="16"/><span>{{item.title}}</span></a><p>Changes are saved automatically.</p></nav>
 <div ref="content" class="settings-document" @scroll.passive="syncNavigation">
  <HookSetup mode="settings">
   <template #global-controls><div class="control-list">
    <div class="control-row"><div class="control-copy"><label id="all-hooks-label" for="all-hooks"><strong>Hook capture for all agents</strong></label><p>Receive session, tool and subagent events from connected agents.</p><small>{{hooksEnabled}} of {{providers.length}} agents enabled</small></div><SwitchRoot id="all-hooks" aria-labelledby="all-hooks-label" class="surface-switch" :model-value="hooksEnabled===providers.length" :disabled="busy||!status" @update:model-value="emit('change',allHookSettings($event))"><SwitchThumb class="surface-thumb"/></SwitchRoot></div>
    <div class="control-row"><div class="control-copy"><label id="all-usage-label" for="all-usage"><strong>Tokens &amp; usage for all agents</strong></label><p>Scan local token counters, API-equivalent cost and available account limits.</p><small>{{usageCount}} of {{providers.length}} agents enabled</small></div><SwitchRoot id="all-usage" aria-labelledby="all-usage-label" class="surface-switch" :model-value="usageCount===providers.length" :disabled="busy||!status" @update:model-value="emit('change',allUsageSettings($event))"><SwitchThumb class="surface-thumb"/></SwitchRoot></div>
    <div class="control-row"><div class="control-copy"><label for="agent-idle"><strong>Agent idle</strong></label><p>Suspend counted agent time after a quiet period without agent activity.</p></div><select id="agent-idle" class="idle-select" :value="status?.surfaces.agentIdleMinutes??5" :disabled="busy||!status" @change="setIdle('agentIdleMinutes',$event)"><option v-for="minutes in idleChoices" :key="minutes" :value="minutes">{{minutes}} {{minutes===1?'minute':'minutes'}}</option></select></div>
   </div></template>
   <template v-for="p in providers" :key="p" #[`${p}-controls`]><div class="control-list">
    <div class="control-row"><div class="control-copy"><label :id="p+'-capture-label'" :for="p+'-capture'"><strong>Capture session hooks</strong></label><p>Track session activity, tools and native subagents.</p><small>{{status?.surfaces[agent(p)?.setting||'']?(status.running?'Capture enabled':'Enabled · collector paused'):'Capture disabled'}}</small></div><SwitchRoot :id="p+'-capture'" :aria-labelledby="p+'-capture-label'" class="surface-switch" :model-value="Boolean(status?.surfaces[agent(p)?.setting||''])" :disabled="busy||!status" @update:model-value="emit('change',{[agent(p)?.setting||'']:$event})"><SwitchThumb class="surface-thumb"/></SwitchRoot></div>
    <div class="control-row"><div class="control-copy"><label :id="p+'-usage-label'" :for="p+'-usage'"><strong>Tokens &amp; usage</strong></label><p>Read usage from captured {{agent(p)?.name}} sessions and available account limits.</p><small>{{usageEnabled(p)?(status?.running?'Scanning enabled':'Enabled · collector paused'):'Scanning disabled'}} · imported history is kept</small></div><SwitchRoot :id="p+'-usage'" :aria-labelledby="p+'-usage-label'" class="surface-switch" :model-value="usageEnabled(p)" :disabled="busy||!status" @update:model-value="setUsage(p,$event)"><SwitchThumb class="surface-thumb"/></SwitchRoot></div>
   </div></template>
  </HookSetup>
  <section id="settings-editors" class="settings-section editors-section" tabindex="-1"><h2>ADE / IDE</h2><p class="section-intro">Connect the environments where your agents work.</p></section>
  <section v-for="source in pollers" :id="'settings-'+source.id" :key="source.id" class="settings-section" tabindex="-1"><h2>{{source.name}}</h2><p class="section-intro">{{source.id==='orca'?'Session discovery and orchestration across shared workspaces.':`Metadata discovery from ${source.name}.`}}</p><div class="control-list"><div class="control-row"><div class="control-copy"><label :id="source.id+'-label'" :for="source.id+'-polling'"><strong>Discover {{source.name}} sessions</strong></label><p>{{source.id==='orca'?'Discover terminals and orchestration runs, and sample worker activity. Overlap with hooks is counted once.':`Collect session metadata from ${source.name}.`}}</p><small>{{status?.surfaces[source.setting]?(status.running?'Discovery enabled':'Enabled · collector paused'):'Discovery disabled'}}</small></div><SwitchRoot :id="source.id+'-polling'" :aria-labelledby="source.id+'-label'" class="surface-switch" :model-value="Boolean(status?.surfaces[source.setting])" :disabled="busy||!status" @update:model-value="emit('change',{[source.setting]:$event})"><SwitchThumb class="surface-thumb"/></SwitchRoot></div></div><p v-if="source.id==='orca'" class="section-note">Orca account hook installation is managed in each agent section.</p></section>
  <section id="settings-browsers" class="settings-section" tabindex="-1"><h2>Browsers</h2><p class="section-intro">Choose which browser tabs Agent Time may read. Website activity records the active page’s URL and title locally.</p><div class="browser-list"><div v-for="browser in browsers" :key="browser.key" class="browser-row"><span :class="['browser-mark',browser.tone]" aria-hidden="true">{{browser.initial}}</span><div class="control-copy"><label :id="browser.key+'-label'" :for="browser.key"><strong>{{browser.name}}</strong></label><p>{{browser.detail}} · active tab only</p><small>{{!status?.surfaces[browser.key]?'Website capture off':!status.surfaces.macosActivity?'On · macOS activity paused':!status.macos?.accessibilityTrusted?'On · Accessibility needed':status.running?'Website capture on':'On · collector paused'}}</small></div><SwitchRoot :id="browser.key" :aria-labelledby="browser.key+'-label'" class="surface-switch" :model-value="status?.surfaces[browser.key]??false" :disabled="busy||!status" @update:model-value="emit('change',{[browser.key]:$event})"><SwitchThumb class="surface-thumb"/></SwitchRoot></div></div><p class="section-note">Turning a browser off stops collecting its page details. Existing history remains available.</p></section>
  <section id="settings-projects" class="settings-section" tabindex="-1"><h2>Projects</h2><p class="section-intro">Connect Linear repository links, review websites assigned to each project, and add exact matching rules.</p><LinearConnection/><WebsiteRules/></section>
  <section id="settings-system" class="settings-section" tabindex="-1"><h2>System</h2><p class="section-intro">macOS permissions and activity tracking.</p><div class="control-list"><div class="control-row"><div class="control-copy"><label id="macos-label" for="macos-activity"><strong>Track macOS activity</strong></label><p>Foreground app, input idle time, and sleep or wake. Human time stays separate from agent time.</p><small>{{status?.surfaces.macosActivity?(status.running?'Tracking enabled':'Enabled · collector paused'):'Tracking disabled'}}</small></div><SwitchRoot id="macos-activity" aria-labelledby="macos-label" class="surface-switch" :model-value="status?.surfaces.macosActivity??false" :disabled="busy||!status" @update:model-value="emit('change',{macosActivity:$event})"><SwitchThumb class="surface-thumb"/></SwitchRoot></div><div class="control-row"><div class="control-copy"><label for="human-idle"><strong>Human idle</strong></label><p>Suspend counted Mac activity after this long without input.</p></div><select id="human-idle" class="idle-select" :value="status?.surfaces.humanIdleMinutes??5" :disabled="busy||!status" @change="setIdle('humanIdleMinutes',$event)"><option v-for="minutes in idleChoices" :key="minutes" :value="minutes">{{minutes}} {{minutes===1?'minute':'minutes'}}</option></select></div></div>
   <div class="control-list startup-list"><div class="control-row"><div class="control-copy"><label id="startup-label" for="startup-item"><strong>Start capture when I sign in</strong></label><p>Start Agent Time in the menu bar with the dashboard hidden. Capture continues while the window is closed.</p><small>{{!native?'Available in the packaged Mac app':!startup?'Checking login item…':startup.status==='enabled'?'Enabled · starts at login':startup.status==='requiresApproval'?'Needs approval in macOS Login Items':'Off · open Agent Time to capture'}}</small></div><SwitchRoot id="startup-item" aria-labelledby="startup-label" class="surface-switch" :model-value="startup?.status==='enabled'" :disabled="!native||!startup||startupBusy" @update:model-value="changeStartup($event)"><SwitchThumb class="surface-thumb"/></SwitchRoot></div><div v-if="startup?.status==='requiresApproval'||startupError" class="startup-note"><p v-if="startupError" role="alert">{{startupError}}</p><button v-if="startup?.status==='requiresApproval'" @click="openStartupSettings">Open Login Items <ArrowUpRight :size="13"/></button></div></div>
   <div class="permission-card"><ShieldCheck :size="19"/><div><h3>Accessibility permission</h3><strong>{{!status?.surfaces.macosActivity?'Activity capture disabled':!status.macos?'Checking permission…':status.macos.accessibilityTrusted?'Granted':'Not granted · basic activity available'}}</strong><p>Foreground app and idle tracking work without Accessibility. Grant it to identify Orca’s selected terminal tab and the active website domain. Unmatched activity stays in the overall human total.</p><button v-if="native" class="permission-button" @click="openPermission">Open System Settings <ArrowUpRight :size="13"/></button><p v-else>Manage permission in System Settings → Privacy &amp; Security → Accessibility.</p></div></div>
   <TrackingCleanup/>
  </section>
  <footer class="settings-footnote"><p>Changes apply immediately. Existing history is kept. Events received from disabled hooks are discarded.</p><p>Closing the window keeps capture running. Quit Agent Time to stop it.</p></footer>
 </div>
</div>
</template>
<style scoped>
.settings-layout{display:flex;flex:1;min-height:0;min-width:0;overflow:hidden}.settings-sidebar{width:176px;flex-shrink:0;padding:30px 14px;background:var(--bg);border-right:1px solid var(--border);overflow:auto}.settings-sidebar h1{font-size:17px;margin:0 10px 24px;letter-spacing:-.35px}.settings-nav{display:flex;align-items:center;gap:9px;color:var(--muted);padding:9px 10px;margin-bottom:3px;border-radius:6px;text-decoration:none;font-size:12px}.settings-nav.child{padding-left:35px;font-size:11px}.settings-nav.active{background:var(--hover);color:var(--text);font-weight:550}.settings-nav:hover{background:var(--hover)}.settings-nav.section-start{margin-top:17px}.settings-sidebar>p{font-size:10px;line-height:1.6;color:var(--muted);margin:24px 10px}.settings-document{flex:1;min-width:0;min-height:0;overflow:auto;padding:30px 30px 36px;position:relative}.settings-section{margin-bottom:38px;scroll-margin-top:24px;outline:none}#settings-system{min-height:calc(100vh - 150px)}.settings-section h2{font-size:20px;letter-spacing:-.35px;margin:0 0 8px}.section-intro{color:var(--muted);font-size:12px;line-height:1.6;margin:0 0 18px}.editors-section{margin-bottom:20px;border-top:1px solid var(--border);padding-top:24px}.control-list{border:1px solid var(--border);border-radius:10px;background:var(--panel);overflow:hidden}.control-row{display:flex;align-items:center;gap:16px;padding:18px 20px;border-bottom:1px solid var(--border)}.control-row:last-child{border:0}.control-copy{flex:1;min-width:0}.control-copy strong{font-size:13px}.control-copy p,.permission-card p{color:var(--muted);font-size:12px;line-height:1.6;margin:6px 0}.control-copy small{font-size:10px;color:var(--muted)}.surface-switch{width:36px;height:21px;border-radius:20px;background:var(--border);padding:2px;flex-shrink:0;transition:background .15s}.surface-switch[data-state=checked]{background:var(--blue)}.surface-thumb{display:block;width:17px;height:17px;background:white;border-radius:50%;box-shadow:0 1px 3px #0003;transition:transform .15s}.surface-thumb[data-state=checked]{transform:translateX(15px)}.browser-list{border:1px solid var(--border);border-radius:10px;background:var(--panel);overflow:hidden}.browser-row{display:flex;align-items:center;gap:14px;padding:15px 20px;border-bottom:1px solid var(--border)}.browser-row:last-child{border:0}.browser-mark{display:grid;place-items:center;width:32px;height:32px;border-radius:9px;flex:none;font-size:17px;font-weight:700;letter-spacing:-1px}.browser-mark.safari{color:#2688dd;background:#2688dd20}.browser-mark.chrome{color:#53a75a;background:#53a75a20}.browser-mark.brave{color:#ed7045;background:#ed704520}.permission-card{display:flex;gap:14px;margin-top:16px;padding:20px;background:var(--panel);border:1px solid var(--border);border-radius:10px}.permission-card>svg{color:var(--muted);flex-shrink:0}.permission-card h3{font-size:13px;margin:0 0 8px}.permission-card strong{font-size:11px;font-weight:500}.permission-button{display:flex;align-items:center;gap:6px;color:var(--blue);padding:7px 0 0;font-size:12px}.section-note,.settings-footnote{font-size:11px;color:var(--muted);line-height:1.6;margin-top:16px}.settings-footnote p{margin:6px 0}.settings-nav:focus-visible,.permission-button:focus-visible,.surface-switch:focus-visible{outline:2px solid var(--blue);outline-offset:3px}@media(max-width:1050px){.settings-sidebar{width:145px;padding-inline:10px}.settings-document{padding-inline:22px}}@media(prefers-reduced-motion:reduce){.surface-switch,.surface-thumb{transition:none}}
.idle-select{flex:none;min-width:115px;border:1px solid var(--border);border-radius:6px;background:var(--panel);color:var(--text);padding:7px 9px;font:inherit;font-size:12px}.idle-select:focus-visible{outline:2px solid var(--blue);outline-offset:3px}.idle-select:disabled{opacity:.5}
.startup-list{margin-top:16px}.startup-note{padding:0 20px 16px;font-size:12px}.startup-note p{color:#d07878;margin:0 0 8px}.startup-note button{display:inline-flex;align-items:center;gap:5px;color:var(--blue)}.startup-note button:focus-visible{outline:2px solid var(--blue);outline-offset:3px}
</style>
